    "content": "{\"id\":\"call_78666fe6e0d44d498df4f777\",\"input\":{\"path\":\"create_pingan_excel.py\",\"content\":\"#!/usr/bin/env python3\\n# -*- coding: utf-8 -*-\\n\\\"\\\"\\\"\\n创建中国平安2024年财务数据Excel报告\\n\\\"\\\"\\\"\\n\\nimport openpyxl\\nfrom openpyxl.styles import Font, Alignment, Border, Side, PatternFill\\nfrom openpyxl.utils import get_column_letter\\n\\n# 创建工作簿\\nwb = openpyxl.Workbook()\\nws = wb.active\\nws.title = \\\"财务数据汇总\\\"\\n\\n# 设置列宽\\nws.column_dimensions['A'].width = 25\\nws.column_dimensions['B'].width = 20\\nws.column_dimensions['C'].width = 15\\nws.column_dimensions['D'].width = 20\\nws.column_dimensions['E'].width = 25\\n\\n# 定义样式\\nheader_font = Font(name='微软雅黑', size=12, bold=True, color='FFFFFF')\\nheader_fill = PatternFill(start_color='4472C4', end_color='4472C4', fill_type='solid')\\ntitle_font = Font(name='微软雅黑', size=16, bold=True)\\ndata_font = Font(name='微软雅黑', size=11)\\nnumber_font = Font(name='微软雅黑', size=11)\\nthin_border = Border(\\n    left=Side(style='thin'),\\n    right=Side(style='thin'),\\n    top=Side(style='thin'),\\n    bottom=Side(style='thin')\\n)\\n\\n# 标题\\nws.merge_cells('A1:E1')\\nws['A1'] = '中国平安保险(集团)股份有限公司2024年度财务数据汇总'\\nws['A1'].font = title_font\\nws['A1'].alignment = Alignment(horizontal='center', vertical='center')\\nws.row_dimensions[1].height = 30\\n\\n# 空行\\nws.row_dimensions[2].height = 15\\n\\n# 表头\\nheaders = ['指标名称', '2024年数值', '单位', '2023年数值', '同比增长率']\\nfor col, header in enumerate(headers, 1):\\n    cell = ws.cell(row=3, column=col)\\n    cell.value = header\\n    cell.font = header_font\\n    cell.fill = header_fill\\n    cell.alignment = Alignment(horizontal='center', vertical='center')\\n    cell.border = thin_border\\nws.row_dimensions[3].height = 25\\n\\n# 数据行\\ndata = [\\n    ['营业收入', 10289.25, '亿元', 9137.89, '+12.6%'],\\n    ['归母净利润', 1266.07, '亿元', 856.65, '+47.8%'],\\n    ['销售费用率*', '注：具体数据需查阅年报详细附注', '', '', ''],\\n    ['研发投入(科技投入)**', 50.70, '亿元(平安银行)', '', '同比下降20.07%'],\\n]\\n\\nfor row_idx, row_data in enumerate(data, 4):\\n    for col_idx, value in enumerate(row_data, 1):\\n        cell = ws.cell(row=row_idx, column=col_idx)\\n        cell.value = value\\n        cell.font = data_font if col_idx == 1 else number_font\\n        cell.alignment = Alignment(horizontal='center' if col_idx > 1 else 'left', vertical='center')\\n        cell.border = thin_border\\n    ws.row_dimensions[row_idx].height = 22\\n\\n# 备注说明\\nws.merge_cells('A9:E9')\\nws['A9'] = '备注说明：'\\nws['A9'].font = Font(name='微软雅黑', size=11, bold=True)\\nws['A9'].alignment = Alignment(vertical='center')\\n\\nnotes = [\\n    '* 销售费用率：保险公司通常披露手续费及佣金支出，而非传统意义上的销售费用率。具体数据需查阅年报中的利润表详细附注。',\\n    '** 研发投入：数据来源为平安银行年报中的IT资本性支出及费用投入，仅为平安银行子公司数据。集团整体的科技投入数据未在公开信息中找到。',\\n]\\n\\nfor idx, note in enumerate(notes, 10):\\n    ws.merge_cells(f'A{idx}:E{idx}')\\n    ws[f'A{idx}'] = note\\n    ws[f'A{idx}'].font = Font(name='微软雅黑', size=10, color='666666')\\n    ws[f'A{idx}'].alignment = Alignment(vertical='center', wrap_text=True)\\n    ws.row_dimensions[idx].height = 30\\n\\n# 数据来源说明\\nws.merge_cells('A12:E12')\\nws['A12'] = '数据来源：中国平安2024年年度报告、公开财务披露信息、联网搜索结果'\\nws['A12'].font = Font(name='微软雅黑', size=10, italic=True, color='666666')\\nws['A12'].alignment = Alignment(vertical='center')\\n\\n# 创建第二个工作表 - 详细数据\\nws2 = wb.create_sheet('业务分部数据')\\n\\n# 设置列宽\\nfor col in range(1, 6):\\n    ws2.column_dimensions[get_column_letter(col)].width = 20\\n\\n# 标题\\nws2.merge_cells('A1:E1')\\nws2['A1'] = '中国平安2024年主要业务板块数据'\\nws2['A1'].font = title_font\\nws2['A1'].alignment = Alignment(horizontal='center', vertical='center')\\nws2.row_dimensions[1].height = 30\\n\\n# 表头\\nheaders2 = ['业务板块', '主要指标', '2024年数值', '单位', '同比变化']\\nfor col, header in enumerate(headers2, 1):\\n    cell = ws2.cell(row=3, column=col)\\n    cell.value = header\\n    cell.font = header_font\\n    cell.fill = header_fill\\n    cell.alignment = Alignment(horizontal='center', vertical='center')\\n    cell.border = thin_border\\n\\n# 业务数据\\nbusiness_data = [\\n    ['寿险及健康险', '新业务价值', 285.34, '亿元', '+28.8%(可比口径)'],\\n    ['寿险及健康险', '新业务价值(调整后)', 400.24, '亿元', '+28.8%(可比口径)'],\\n    ['产险', '保险服务收入', 3281.46, '亿元', '+4.7%'],\\n    ['产险', '净利润', 150.21, '亿元', '+67.7%'],\\n    ['产险', '综合成本率', 98.3, '%', '优化2.3个百分点'],\\n    ['银行', '净利润', 445.08, '亿元', ''],\\n    ['银行', '不良贷款率', 1.06, '%', ''],\\n    ['集团', '总资产', 129578.27, '亿元', '+11.9%'],\\n    ['集团', '保险资金投资规模', 57314.09, '亿元', '+21.4%'],\\n    ['集团', '综合投资收益率', 5.8, '%', '+2.2个百分点'],\\n    ['集团', '个人客户数', 2.42, '亿人', ''],\\n]\\n\\nfor row_idx, row_data in enumerate(business_data, 4):\\n    for col_idx, value in enumerate(row_data, 1):\\n        cell = ws2.cell(row=row_idx, column=col_idx)\\n        cell.value = value\\n        cell.font = data_font if col_idx == 1 else number_font\\n        cell.alignment = Alignment(horizontal='center' if col_idx > 1 else 'left', vertical='center')\\n        cell.border = thin_border\\n    ws2.row_dimensions[row_idx].height = 22\\n\\n# 创建第三个工作表 - 关键财务指标\\nws3 = wb.create_sheet('关键财务指标')\\n\\n# 设置列宽\\nfor col in range(1, 5):\\n    ws3.column_dimensions[get_column_letter(col)].width = 25\\n\\n# 标题\\nws3.merge_cells('A1:D1')\\nws3['A1'] = '中国平安2024年关键财务指标'\\nws3['A1'].font = title_font\\nws3['A1'].alignment = Alignment(horizontal='center', vertical='center')\\nws3.row_dimensions[1].height = 30\\n\\n# 表头\\nheaders3 = ['指标', '2024年', '2023年', '变化']\\nfor col, header in enumerate(headers3, 1):\\n    cell = ws3.cell(row=3, column=col)\\n    cell.value = header\\n    cell.font = header_font\\n    cell.fill = header_fill\\n    cell.alignment = Alignment(horizontal='center', vertical='center')\\n    cell.border = thin_border\\n\\n# 关键指标数据\\nkey_data = [\\n    ['归母营运利润', '1218.62亿元', '', '+9.1%'],\\n    ['基本每股收益', '7.16元', '', '+47.9%'],\\n    ['加权平均ROE', '13.8%', '', '+4.1个百分点'],\\n    ['每股净资产', '50.99元', '', '+3.3%'],\\n    ['每股股息', '2.55元', '', '+5%'],\\n    ['分红比例', '37.9%', '', ''],\\n    ['内含价值', '14207亿元', '', '+2.2%'],\\n    ['客户留存率(4+合同)', '98%', '', ''],\\n]\\n\\nfor row_idx, row_data in enumerate(key_data, 4):\\n    for col_idx, value in enumerate(row_data, 1):\\n        cell = ws3.cell(row=row_idx, column=col_idx)\\n        cell.value = value\\n        cell.font = data_font if col_idx == 1 else number_font\\n        cell.alignment = Alignment(horizontal='center' if col_idx > 1 else 'left', vertical='center')\\n        cell.border = thin_border\\n    ws3.row_dimensions[row_idx].height = 22\\n\\n# 保存文件\\noutput_file = '平安人寿2024年度财务数据.xlsx'\\nwb.save(output_file)\\nprint(f\\\"Excel文件已创建: {output_file}\\\")\\n\"},\"metadata\":{},\"name\":\"文件写入\",\"state\":\"PENDING\"}",
